style.css:
input[name="q"] {
  border: 2px solid #7b2ff7 !important;
  box-shadow: 0 0 10px #7b2ff7, 0 0 20px #2b1055 !important;
  border-radius: 12px !important;
  transition: 0.3s ease-in-out;
}

input[name="q"]:focus {
  box-shadow: 0 0 20px #9a4efc, 0 0 40px #2b1055 !important;
  border-color: #9a4efc !important;
}
